from ..logger import LOGGER


def log_states(states, state):
    """Log message in format TRX-002 operationalState: WO"""
    for trx_data in states:
        LOGGER.info("{} {}State: {}".format(trx_data[0], state, trx_data[1]))


def log_status(states_list):
    """Log message in format BTS-141 administrativeStat: U, operationalState: WO"""
    for sts in states_list:
        LOGGER.info('{} administrativeState: {}, operationalState: {}'.format(sts[0], sts[1], sts[2]))
